        },
      ];

      const result = await detectPromptPattern('', prompts);
      expect(result).toBeNull();
    });

    it('should handle null output gracefully', async () => {
      const prompts: InteractivePromptOutput[] = [
        {
          detector: (): boolean => true,
          response: 'should-not-match',
